MATLAB 程序：exe821.m

global a b beta R

a=1; b=2; beta=0.5; R=2;

t=0:0.01:6;

e0=$-2 0$';

[t,e2]=ode23('sys821',t,e0);

ed=-10,0.01,10;

e3=1-beta*ed;

e4=-1-beta*ed;

plot(e3,ed,'-',e4,ed,'-');

hold on;

plot(e2(:,1),e2(:,2));

